mapper.update:
UPDATE stellar_wallet
SET balance = balance - #{amount},
    version = version + 1
WHERE user_id = #{userId}
  AND version = #{oldVersion}
  AND balance >= #{amount}

UPDATE stellar_wallet
SET balance = balance + #{amount},
    version = version + 1
WHERE user_id = #{userId}
  AND version = #{oldVersion}

UPDATE stellar_wallet
SET total_recharge = total_recharge + #{amount}
WHERE user_id = #{userId}

UPDATE stellar_wallet
SET total_spent = total_spent + #{amount}
WHERE user_id = #{userId}

mapper.select:
SELECT id, wallet_id, user_id, type, amount, balance_after, channel,
       biz_type, biz_id, remark, create_time
FROM stellar_wallet_transaction
WHERE user_id = #{userId}
ORDER BY id DESC
LIMIT #{offset}, #{limit}
